INSERT INTO essentials.citations (subject_type, subject_id, claim, url, title, publisher, retrieved_on, archive_url, note, added_by)
SELECT 'office_term', ot.id, 'holder', h.url, h.ttl, h.publisher, h.on_day, h.archive_url, h.note, 'CA_0421'
FROM c_holder h
JOIN essentials.governments g ON g.name = h.gov
JOIN essentials.chambers c ON c.government_id = g.id
JOIN essentials.offices o ON o.chamber_id = c.id AND o.title = h.title
 AND (h.ordinal IS NULL OR o.description LIKE 'Internal ordinal ' || h.ordinal || ' of ' || h.of_n || '.%')
JOIN essentials.districts d ON d.id = o.district_id AND d.geo_id = h.geo AND d.district_type = 'LOCAL' AND lower(d.state) = 'in'
JOIN essentials.office_terms ot ON ot.office_id = o.id AND ot.term_end IS NULL AND ot.politician_id IS NOT NULL
ON CONFLICT (subject_type, subject_id, claim, url) DO NOTHING;

INSERT INTO essentials.citations (subject_type, subject_id, claim, url, title, publisher, retrieved_on, archive_url, note, added_by)
