JOIN essentials.geofence_boundaries gb ON gb.geo_id = v.geo AND gb.mtfcc = 'X0091'
ON CONFLICT (subject_type, subject_id, claim, url) DO NOTHING;

INSERT INTO essentials.citations (subject_type, subject_id, claim, url, title, publisher, retrieved_on, archive_url, note, added_by)
SELECT 'office', o.id, 'vacancy', h.url, h.ttl, h.publisher, h.on_day, h.archive_url, h.note, 'CA_0421'
FROM (VALUES
  ('City of Muncie, Indiana, US', 'muncie-in-council-district-4', 'Council Member, District 4', NULL, NULL, NULL, 'https://muncievoice.com/40790/surveillance-ordinance-filed-in-muncie-introduction-set-for-dec-7/', NULL, 'Surveillance Ordinance Filed In Muncie; Introduction Set For Dec. 7', 'Muncie Voice', DATE '2026-11-24', 'Sara Gullion resigned from the Council on winning Indiana House District 34; caucus 2026-11-30.')
) AS h(gov, geo, title, ordinal, of_n, name, url, archive_url, ttl, publisher, on_day, note)
JOIN essentials.governments g ON g.name = h.gov
JOIN essentials.chambers c ON c.government_id = g.id
JOIN essentials.offices o ON o.chamber_id = c.id AND o.title = h.title
 AND (h.ordinal IS NULL OR o.description LIKE 'Internal ordinal ' || h.ordinal || ' of ' || h.of_n || '.%')
JOIN essentials.districts d ON d.id = o.district_id AND d.geo_id = h.geo AND d.district_type = 'LOCAL' AND lower(d.state) = 'in'
ON CONFLICT (subject_type, subject_id, claim, url) DO NOTHING;

-- ─── Post-verify ─────────────────────────────────────────────────────────────
DO $$
DECLARE v_n int; v_orphan int; v_wrong text; v_vac int;
BEGIN
  SELECT count(*) INTO v_n FROM essentials.citations WHERE added_by = 'CA_0421';
  IF v_n <> 241 THEN RAISE EXCEPTION 'CA_0421: % citations written, expected 241', v_n; END IF;

  SELECT count(*) INTO v_n FROM essentials.citations WHERE added_by = 'CA_0421' AND claim = 'holder';
  IF v_n <> 138 THEN RAISE EXCEPTION 'CA_0421: % holder citations, expected 138 (an office had no current term?)', v_n; END IF;
  SELECT count(*) INTO v_n FROM essentials.citations WHERE added_by = 'CA_0421' AND claim = 'boundary';
  IF v_n <> 76 THEN RAISE EXCEPTION 'CA_0421: % boundary citations, expected 76 (a district map is not loaded?)', v_n; END IF;

  -- Every subject exists (the table has no foreign key, so this is the only guard).
  SELECT count(*) INTO v_orphan FROM essentials.citations c WHERE c.added_by = 'CA_0421' AND NOT CASE c.subject_type
      WHEN 'office_term'       THEN EXISTS (SELECT 1 FROM essentials.office_terms x WHERE x.id = c.subject_id)
      WHEN 'office'            THEN EXISTS (SELECT 1 FROM essentials.offices x WHERE x.id = c.subject_id)
      WHEN 'government'        THEN EXISTS (SELECT 1 FROM essentials.governments x WHERE x.id = c.subject_id)
      WHEN 'geofence_boundary' THEN EXISTS (SELECT 1 FROM essentials.geofence_boundaries x WHERE x.id = c.subject_id)
      WHEN 'politician'        THEN EXISTS (SELECT 1 FROM essentials.politicians x WHERE x.id = c.subject_id)
      ELSE false END;
  IF v_orphan <> 0 THEN RAISE EXCEPTION 'CA_0421: % citations point at no record', v_orphan; END IF;

  -- A holder citation must vouch for the person actually seated: compare surnames, folded.
  SELECT string_agg(h.name || ' vs ' || p.full_name, '; ') INTO v_wrong
  FROM c_holder h
JOIN essentials.governments g ON g.name = h.gov
JOIN essentials.chambers c ON c.government_id = g.id
JOIN essentials.offices o ON o.chamber_id = c.id AND o.title = h.title
 AND (h.ordinal IS NULL OR o.description LIKE 'Internal ordinal ' || h.ordinal || ' of ' || h.of_n || '.%')
JOIN essentials.districts d ON d.id = o.district_id AND d.geo_id = h.geo AND d.district_type = 'LOCAL' AND lower(d.state) = 'in'
  JOIN essentials.office_terms ot ON ot.office_id = o.id AND ot.term_end IS NULL
  JOIN essentials.politicians p ON p.id = ot.politician_id
  WHERE position(lower(p.last_name) IN lower(h.name)) = 0;
  IF v_wrong IS NOT NULL THEN RAISE EXCEPTION 'CA_0421: holder citation names a different person than the seat holds: %', v_wrong; END IF;

  -- Every office in these cities is either cited as held or cited as vacant.
  SELECT count(*) INTO v_vac FROM essentials.offices o
    JOIN essentials.chambers c ON c.id = o.chamber_id JOIN essentials.governments g ON g.id = c.government_id
   WHERE g.name IN ('City of Evansville, Indiana, US', 'City of South Bend, Indiana, US', 'City of Carmel, Indiana, US', 'City of Lafayette, Indiana, US', 'City of Muncie, Indiana, US', 'City of Westfield, Indiana, US', 'City of Terre Haute, Indiana, US', 'City of Elkhart, Indiana, US', 'City of Jeffersonville, Indiana, US', 'City of Mishawaka, Indiana, US', 'City of Lawrence, Indiana, US', 'City of New Albany, Indiana, US', 'City of Goshen, Indiana, US')
     AND NOT EXISTS (SELECT 1 FROM essentials.office_terms ot JOIN essentials.citations ci
                       ON ci.subject_type = 'office_term' AND ci.subject_id = ot.id AND ci.claim = 'holder'
                     WHERE ot.office_id = o.id AND ot.term_end IS NULL)
     AND NOT EXISTS (SELECT 1 FROM essentials.citations ci WHERE ci.subject_type = 'office' AND ci.subject_id = o.id AND ci.claim = 'vacancy');
  IF v_vac <> 0 THEN RAISE EXCEPTION 'CA_0421: % offices in these cities have no holder or vacancy citation', v_vac; END IF;

  RAISE NOTICE 'CA_0421 OK: 241 citations (138 holder, 26 structure, 76 boundary, 1 vacancy, 0 name), 0 orphans, every office cited';
END $$;

COMMIT;
